SourceRef ref(const char* kind,const StableId& id){return {"military",kind,id};}
WorldMoment until(const MilitaryDutyTerms& t,ExactArithmeticBudget b){return take(normalize_world_moment(t.until_tick,{},b));}
void current(const MilitaryDutyContext& c,const WorldMoment& at){if(!same_moment(take(c.stamps.read_current_moment()),at,c.budget))fail("MilitaryDutyActualMomentRequired");}
const MilitaryDutyRule& rule(const MilitaryDutyContext& c,const MilitaryDutyTerms& t){const auto* r=c.catalog.rules.find(t.duty_rule_id);if(!r||r->version!=t.duty_rule_version||r->kind!=t.duty_kind||r->qualified_period_policy_ref!=t.qualified_period_policy_ref)fail("MilitaryDutyAcceptedRuleRequired",t.duty_action_id);return *r;}
MilitaryDutyTerms& terms(MilitaryDutyState& s,const StableId& id){auto* t=s.terms.find(id);if(!t)fail("MilitaryDutyTermsRequired",id);return *t;}
const MilitaryDutyTerms& terms(const MilitaryDutyState& s,const StableId& id){const auto* t=s.terms.find(id);if(!t)fail("MilitaryDutyTermsRequired",id);return *t;}
MilitaryDutyExecution& execution(MilitaryDutyState& s,const StableId& id){auto* e=s.executions.find(id);if(!e)fail("MilitaryDutyExecutionRequired",id);return *e;}
void ids(const std::vector<StableId>& v,const char* code){std::set<StableId> seen;for(const auto& x:v)if(x.empty()||!seen.insert(x).second)fail(code,x);}
bool same_refs(const std::vector<MomentOwnerSource>& a,const std::vector<MomentOwnerSource>& b){if(a.size()!=b.size())return false;for(std::size_t i=0;i<a.size();++i)if(a[i].source_schema!=b[i].source_schema||!same_source(a[i].source_ref,b[i].source_ref))return false;return true;}
bool same_optional(const std::optional<MomentOwnerSource>& a,const std::optional<MomentOwnerSource>& b){return bool(a)==bool(b)&&(!a||(a->source_schema==b->source_schema&&same_source(a->source_ref,b->source_ref)));}
bool same_participants(const std::vector<MilitaryParticipationRef>& a,const std::vector<MilitaryParticipationRef>& b){if(a.size()!=b.size())return false;for(std::size_t i=0;i<a.size();++i)if(a[i].actor_id!=b[i].actor_id||a[i].owner_activity_id!=b[i].owner_activity_id||a[i].occupation_source_id!=b[i].occupation_source_id||a[i].occupation_version!=b[i].occupation_version)return false;return true;}
bool same_common_prefix(const CommonActualFactPrefix& a,const CommonActualFactPrefix& b){return a.common_fact_count==b.common_fact_count&&bool(a.last_common_fact)==bool(b.last_common_fact)&&(!a.last_common_fact||same_source(*a.last_common_fact,*b.last_common_fact));}
bool same_common_prefix(const CommonActualFactPrefix& a,const CurrentCommonFactPrefix& b){return a.common_fact_count==b.common_fact_count&&bool(a.last_common_fact)==bool(b.last_common_fact)&&(!a.last_common_fact||(a.last_common_fact->domain==b.last_common_fact->domain&&a.last_common_fact->kind==b.last_common_fact->kind&&a.last_common_fact->id==b.last_common_fact->id));}
bool same_condition_prefix(const CharacterConditionAppliedPrefix& a,const CharacterConditionAppliedPrefix& b){return a.applied_receipt_count==b.applied_receipt_count&&bool(a.last_applied_receipt)==bool(b.last_applied_receipt)&&(!a.last_applied_receipt||a.last_applied_receipt->result_id==b.last_applied_receipt->result_id);}
bool same_condition_head(const ActorConditionHead& a,const ActorConditionHead& b){return a.actor_id==b.actor_id&&a.condition_revision==b.condition_revision&&a.initial_condition_seed_ref.seed_key==b.initial_condition_seed_ref.seed_key&&bool(a.latest_receipt_ref)==bool(b.latest_receipt_ref)&&(!a.latest_receipt_ref||a.latest_receipt_ref->result_id==b.latest_receipt_ref->result_id);}
bool same_consumption(const std::optional<MilitaryDutyConditionConsumption>& a,const std::optional<MilitaryDutyConditionConsumption>& b){if(bool(a)!=bool(b))return false;if(!a)return true;if(!same_common_prefix(a->common_prefix,b->common_prefix)||!same_condition_prefix(a->condition_prefix,b->condition_prefix)||a->consumed_heads.size()!=b->consumed_heads.size())return false;for(std::size_t i=0;i<a->consumed_heads.size();++i)if(!same_condition_head(a->consumed_heads[i],b->consumed_heads[i]))return false;return true;}
const CharacterConditionSources& condition_sources(const CommonStore& common,const MilitaryDutyContext& c){if(!c.condition_sources||&c.condition_sources->common!=&common)fail("MilitaryDutyConditionSourcesRequired");return *c.condition_sources;}
void validate_condition_consumption_current(const CommonStore& common,const MilitaryDutyContext& c,const MomentSpan& span,const MilitaryDutyQualification& q,const CommonActualFactPrefix& capture){
 if(c.selected_dynamic_military!=4){if(q.condition_consumption)fail("MilitaryDutyConditionConsumptionRequires4");return;}
 if(!q.condition_consumption)fail("MilitaryDutyConditionConsumptionRequired");
 const auto& s=condition_sources(common,c);const auto& observed=*q.condition_consumption;
 auto unchanged=[&]{
  if(!same_moment(take(c.stamps.read_current_moment()),span.to,c.budget)||!same_moment(s.actual_now,span.to,c.budget))fail("MilitaryDutyConditionCaptureMomentMismatch");
  take(read_actual_common_fact_prefix(common,capture));
  if(!same_common_prefix(observed.common_prefix,capture)||!same_common_prefix(capture,take(read_current_common_fact_prefix(common)))||!same_condition_prefix(observed.condition_prefix,take(capture_character_condition_applied_prefix(s))))fail("MilitaryDutyConditionCaptureChanged");
 };
 unchanged();
 for(std::size_t i=0;i<observed.consumed_heads.size();++i){
  const auto& head=observed.consumed_heads[i];if(head.actor_id.empty())fail("MilitaryDutyConditionHeadRequired");
  for(std::size_t j=0;j<i;++j)if(observed.consumed_heads[j].actor_id==head.actor_id)fail("MilitaryDutyDuplicateConditionHead",head.actor_id);
  const auto* actual=take(read_verified_current_character_condition_head(s,common,s.state,head.actor_id,c.stamps));
  if(!actual||!same_condition_head(*actual,head))fail("MilitaryDutyConditionCurrentHeadMismatch",head.actor_id);
 }
 unchanged();
 // The native original source closure must remain read-only. These checks are
 // not a rollback epoch, and do not replace its actor-coverage/purpose proof.
 for(const auto& head:observed.consumed_heads){const auto* actual=s.state.character_condition_extensions.actor_condition_heads.find(head.actor_id);if(!actual||!same_condition_head(*actual,head))fail("MilitaryDutyConditionCaptureChanged",head.actor_id);}
}
bool same_qualification(const MilitaryDutyQualification& a,const MilitaryDutyQualification& b){return same_participants(a.actual_participant_refs,b.actual_participant_refs)&&a.actual_member_ids==b.actual_member_ids&&a.eligible_force_member_ids==b.eligible_force_member_ids&&a.leader_present==b.leader_present&&a.authority_valid==b.authority_valid&&a.route_or_station_valid==b.route_or_station_valid&&a.supplied==b.supplied&&same_refs(a.participant_basis_refs,b.participant_basis_refs)&&same_refs(a.route_or_station_sources,b.route_or_station_sources)&&same_refs(a.supply_sources,b.supply_sources)&&same_refs(a.authority_sources,b.authority_sources)&&same_refs(a.encounter_result_refs,b.encounter_result_refs)&&same_refs(a.unresolved_conflict_refs,b.unresolved_conflict_refs)&&same_optional(a.unavailable_cause,b.unavailable_cause)&&same_consumption(a.condition_consumption,b.condition_consumption);}
void append(std::vector<MomentOwnerSource>& out,const std::vector<MomentOwnerSource>& add){for(const auto& source:add){if(source.source_schema<1||!source_valid(source.source_ref))fail("MilitaryDutyOriginalSourceRequired");if(std::none_of(out.begin(),out.end(),[&](const auto& old){return old.source_schema==source.source_schema&&same_source(old.source_ref,source.source_ref);}))out.push_back(source);}}
void check_qualification(const MilitaryDutyTerms& t,const MilitaryDutyQualification& q){ids(q.actual_member_ids,"MilitaryDutyDuplicateMember");ids(q.eligible_force_member_ids,"MilitaryDutyDuplicateEligibleMember");std::set<StableId> participants;for(const auto& p:q.actual_participant_refs)if(p.actor_id.empty()||p.owner_activity_id.empty()||p.occupation_source_id.empty()||p.occupation_version<1||!participants.insert(p.actor_id).second)fail("MilitaryDutyParticipationSourceRequired",t.duty_action_id);for(const auto& id:q.eligible_force_member_ids)if(std::find(q.actual_member_ids.begin(),q.actual_member_ids.end(),id)==q.actual_member_ids.end())fail("MilitaryDutyEligibilityNotActualMember",id);if(q.leader_present&&!participants.count(t.leader_actor_id))fail("MilitaryDutyLeaderParticipationRequired",t.duty_action_id);if(q.participant_basis_refs.empty()||q.authority_sources.empty()||(q.route_or_station_valid&&q.route_or_station_sources.empty())||(q.supplied&&q.supply_sources.empty()))fail("MilitaryDutyQualificationSourcesRequired",t.duty_action_id);std::vector<MomentOwnerSource> checked;for(const auto* sources:{&q.participant_basis_refs,&q.route_or_station_sources,&q.supply_sources,&q.authority_sources,&q.encounter_result_refs,&q.unresolved_conflict_refs})append(checked,*sources);if(q.unavailable_cause)append(checked,{*q.unavailable_cause});}
bool qualified(const MilitaryDutyRule& r,const MilitaryDutyQualification& q){return q.authority_valid&&q.route_or_station_valid&&(!r.requires_supply||q.supplied)&&(!r.requires_leader||q.leader_present)&&Integer(q.eligible_force_member_ids.size())>=r.minimum_eligible_force_members&&(!r.rejects_conflict||q.unresolved_conflict_refs.empty())&&!q.unavailable_cause;}
void fold(MilitaryDutyWindowState& w,const MilitaryDutyQualification& q){w.min_eligible_force_members=std::min(w.min_eligible_force_members,Integer(q.eligible_force_member_ids.size()));w.leader_present_throughout=w.leader_present_throughout&&q.leader_present;for(const auto* v:{&q.participant_basis_refs,&q.route_or_station_sources,&q.supply_sources,&q.authority_sources})append(w.qualification_source_refs,*v);append(w.conflict_source_refs,q.unresolved_conflict_refs);}
const MilitaryStationActionSource* station(const MilitaryDutyState& s,const StableId& duty){const MilitaryStationActionSource* out=nullptr;for(const auto& row:s.station_sources.rows())if(row.second.duty_action_id==duty){if(out)fail("DuplicateMilitaryStationSource",duty);out=&row.second;}return out;}
const MilitaryStationTerminalSource* terminal(const MilitaryDutyState& s,const StableId& station_id){const MilitaryStationTerminalSource* out=nullptr;for(const auto& row:s.station_terminals.rows())if(row.second.station_source_ref==station_id){if(out)fail("DuplicateMilitaryStationTerminal",station_id);out=&row.second;}return out;}
WorldMoment source_moment(const MilitaryDutyState& s,const MilitaryDutyContext& c,const MomentOwnerSource& source){if(source.source_ref.domain=="military"&&source.source_schema==1){if(source.source_ref.kind=="military_duty_execution_stopped"){for(const auto& row:s.executions.rows())if(row.second.movement_stop&&row.second.movement_stop->id==source.source_ref.id)return row.second.movement_stop->stopped_at;fail("MilitaryDutyMovementStopSourceRequired");}if(source.source_ref.kind=="military_duty_execution_bound"){for(const auto& row:s.executions.rows())if(row.second.actual_binding&&row.second.actual_binding->id==source.source_ref.id)return row.second.actual_binding->bound_at;fail("MilitaryDutyMovementBindingSourceRequired");}if(source.source_ref.kind=="military_duty_control"){const auto* r=s.controls.find(source.source_ref.id);if(!r)fail("MilitaryDutyControlRequired");return r->occurred_at;}if(source.source_ref.kind=="military_station_terminal"){const auto* r=s.station_terminals.find(source.source_ref.id);if(!r)fail("MilitaryStationTerminalRequired");return r->ended_at;}}return take(c.original.read_actual_source_moment(source));}
void end_station(CommonStore& common,MilitaryDutyState& state,const MilitaryDutyContext& c,const MilitaryDutyTerms& t,const WorldMoment& at,const MomentOwnerSource& cause,bool expired,const std::function<Status(const StableId&)>& release){const auto* original=station(state,t.duty_action_id);if(!original||terminal(state,original->id))return;if(!release)fail("MilitaryStationOriginalReleaseRequired",t.duty_action_id);MilitaryStationTerminalSource end;end.id=take(common.next_id("military_station_terminal"));end.station_source_ref=original->id;end.ended_at=at;end.original_cause=cause;end.authorization_expired=expired;const auto action=original->actual_action.id;state.station_terminals.set(end.id,end);take(common.append_fact({end.id,"military_station_terminal","military"}));take(release(action));if(common.action(action))fail("MilitaryStationActionNotReleased",action);}
