Status validate_military_duty_selected_layout(const MilitaryDutyState& state,Integer selected){return status([&]{
 if(selected!=2&&selected!=3&&selected!=4)fail("MilitaryDutySelectedSchemaRequired");
 if(selected!=4&&!state.assignments.empty())fail("MilitaryDutyAssignmentsRequire4");
 auto q=[&](const MilitaryDutyQualification& value){if(selected==4&&!value.condition_consumption)fail("MilitaryDutyConditionConsumptionRequired");if(selected!=4&&value.condition_consumption)fail("MilitaryDutyConditionConsumptionRequires4");};
 for(const auto& row:state.windows.rows()){
  q(row.second.opening_qualification);
  for(const auto& segment:row.second.actual_segments)q(segment.qualification);
  if(row.second.closing_qualification)q(*row.second.closing_qualification);
 }
});}
Status validate_military_duty_qualification_history_use(const CommonStore& common,const MilitaryDutyState& state,const MilitaryDutyContext& c,const MilitaryDutyTerms& t,const MilitaryDutyServiceSegment& segment,const CommonActualFactPrefix& capture,const MilitaryDutyQualificationHistoryUse& use){return status([&]{
 using Kind=MilitaryDutyQualificationHistoryUse::Kind;
 if(use.kind==Kind::current_capture){
  if(use.window||use.segment_index)fail("MilitaryDutyQualificationCurrentUseMismatch");
  if(!same_moment(take(c.stamps.read_current_moment()),segment.span.to,c.budget)||!same_common_prefix(capture,take(read_current_common_fact_prefix(common))))fail("MilitaryDutyQualificationCurrentCaptureRequired");
  validate_condition_consumption_current(common,c,segment.span,segment.qualification,capture);return;
 }
 const auto* w=use.window;
 if(!w||state.windows.find(w->id)!=w||w->window.duty_action_id!=t.duty_action_id)fail("MilitaryDutyQualificationWindowOwnerRequired");
 const auto* wh=common.state().facts.find(w->id);
 if(!wh||wh->id!=w->id||wh->domain!="military"||wh->kind!="military_duty_window")fail("MilitaryDutyQualificationWindowSourceRequired",w->id);
 const auto opening=take(read_actual_common_fact_prefix_before(common,SourceRefBuildView{"military","military_duty_window",w->id})).common_fact_count;
 const MilitaryDutyPeriodFact2* period=nullptr;
 if(const auto* closed=std::get_if<DutyWindowClosed>(&w->state)){
  period=state.period_facts.find(closed->result_ref);const auto* ph=common.state().facts.find(closed->result_ref);
  if(!period||period->fact_id!=closed->result_ref||!ph||ph->id!=closed->result_ref||ph->domain!="military"||ph->kind!="military_duty_period"||period->window.duty_action_id!=w->window.duty_action_id||period->window.service_epoch!=w->window.service_epoch||period->window.ordinal!=w->window.ordinal||!same_moment(period->window.opened_at,w->window.opened_at,c.budget)||!same_moment(period->window.planned_close_at,w->window.planned_close_at,c.budget)||!same_moment(period->actual_until,w->last_accounted_at,c.budget))fail("MilitaryDutyQualificationPeriodOwnerRequired",w->id);
 }
 const MilitaryDutyQualification* saved=nullptr;const MilitaryDutyQualification* prior=nullptr;
 if(use.kind==Kind::window_opening){
  if(use.segment_index||!same_moment(segment.span.from,w->window.opened_at,c.budget)||!same_moment(segment.span.to,w->window.opened_at,c.budget)||!same_common_prefix(capture,take(read_actual_common_fact_prefix_before(common,SourceRefBuildView{"military","military_duty_window",w->id}))))fail("MilitaryDutyQualificationOpeningUseMismatch",w->id);
  saved=&w->opening_qualification;
 }else{
  const bool enclosing=period?same_common_prefix(capture,take(read_actual_common_fact_prefix_before(common,SourceRefBuildView{"military","military_duty_period",period->fact_id}))):same_common_prefix(capture,take(read_current_common_fact_prefix(common)));
  if(!enclosing||capture.common_fact_count<=opening)fail("MilitaryDutyQualificationEnclosingCaptureMismatch",w->id);
  if(use.kind==Kind::window_segment){
   if(use.segment_index>=w->actual_segments.size())fail("MilitaryDutyQualificationSegmentUseMismatch",w->id);
   const auto& actual=w->actual_segments[use.segment_index];
   if(!same_moment(segment.span.from,actual.span.from,c.budget)||!same_moment(segment.span.to,actual.span.to,c.budget))fail("MilitaryDutyQualificationSegmentUseMismatch",w->id);
   saved=&actual.qualification;prior=use.segment_index?&w->actual_segments[use.segment_index-1].qualification:&w->opening_qualification;
  }else if(use.kind==Kind::window_closing){
   if(use.segment_index||!period||!w->closing_qualification||!same_moment(segment.span.from,w->last_accounted_at,c.budget)||!same_moment(segment.span.to,w->last_accounted_at,c.budget))fail("MilitaryDutyQualificationClosingUseMismatch",w->id);
   saved=&*w->closing_qualification;prior=w->actual_segments.empty()?&w->opening_qualification:&w->actual_segments.back().qualification;
  }else fail("MilitaryDutyQualificationUseKindInvalid",w->id);
 }
 if(!saved||!same_qualification(segment.qualification,*saved))fail("MilitaryDutyQualificationSlotMismatch",w->id);
 take(read_actual_common_fact_prefix(common,capture));
 if(c.selected_dynamic_military!=4){if(saved->condition_consumption)fail("MilitaryDutyConditionConsumptionRequires4",w->id);return;}
 if(!saved->condition_consumption)fail("MilitaryDutyConditionConsumptionRequired",w->id);
 const auto& s=condition_sources(common,c);const auto& observed=*saved->condition_consumption;
 take(read_actual_common_fact_prefix(common,observed.common_prefix));
 take(validate_character_condition_applied_prefix(s,observed.condition_prefix));
 if(use.kind==Kind::window_segment){if(observed.common_prefix.common_fact_count<=opening||observed.common_prefix.common_fact_count>capture.common_fact_count)fail("MilitaryDutyQualificationSegmentCaptureMismatch",w->id);}
 else if(!same_common_prefix(observed.common_prefix,capture))fail("MilitaryDutyQualificationPointCaptureMismatch",w->id);
 if(prior){
  if(!prior->condition_consumption)fail("MilitaryDutyConditionConsumptionRequired",w->id);
  const auto& before=*prior->condition_consumption;take(read_actual_common_fact_prefix(common,before.common_prefix));take(validate_character_condition_applied_prefix(s,before.condition_prefix));
  if(before.common_prefix.common_fact_count>observed.common_prefix.common_fact_count||before.condition_prefix.applied_receipt_count>observed.condition_prefix.applied_receipt_count)fail("MilitaryDutyConditionCaptureOrderMismatch",w->id);
 }
 for(std::size_t i=0;i<observed.consumed_heads.size();++i){
  const auto& head=observed.consumed_heads[i];if(head.actor_id.empty())fail("MilitaryDutyConditionHeadRequired",w->id);
  for(std::size_t j=0;j<i;++j)if(observed.consumed_heads[j].actor_id==head.actor_id)fail("MilitaryDutyDuplicateConditionHead",head.actor_id);
  const auto actual=take(read_character_condition_at_applied_prefix(s,head.actor_id,observed.condition_prefix,segment.span.to));
  if(!same_condition_head(actual.head,head))fail("MilitaryDutyConditionConsumedHeadMismatch",head.actor_id);
 }
 // Head validity is not required-actor coverage. The original qualification
 // validator still proves the real roster, all purposes and half-open slices.
});}
Status validate_military_duty_catalog(const MilitaryDutyCatalog& catalog){
  // 只旁观本次原入口；返回值与首错仍由原函数独占。
  ::hanmo::resident::catalog_section_observation::Scope catalog_cost_observation(
      ::hanmo::resident::catalog_section_observation::Kind::catalog_validation, 78, "MilitaryDutyCatalog", "validate_military_duty_catalog", &catalog);
return status([&]{for(const auto& row:catalog.rules.rows()){const auto& r=row.second;if(row.first!=r.id||r.id.empty()||r.version.empty()||r.maximum_authorization_half_days<=0||r.minimum_eligible_force_members<0||r.qualified_period_policy_ref.empty()||r.leader_capability_purpose_ref.empty()||r.member_capability_purpose_ref.empty())fail("InvalidMilitaryDutyRule",row.first);}});}
Outcome<MilitaryDutyStartResult> start_military_duty_in_candidate(CommonStore& common,MilitaryDutyState& state,const MilitaryDutyContext& c,const StartMilitaryDuty& request,const WorldMoment& at){return guard<MilitaryDutyStartResult>([&]{current(c,at);take(validate_military_duty_catalog(c.catalog));if(c.selected_dynamic_military==4&&(!c.assignments||!c.assignments->bound_to(common,state,c.catalog)))fail("MilitaryDutyAssignmentOriginalSourcesRequired");auto accepted=take(c.original.read_start(request,at));if(c.selected_dynamic_military==4&&(accepted.assignment_source.source_schema!=1||accepted.assignment_source.source_ref.domain!="military"||accepted.assignment_source.source_ref.kind!="military_duty_assignment"))fail("MilitaryDutyNativeAssignmentSourceRequired");auto t=std::move(accepted.accepted_terms);if(c.selected_dynamic_military==4){const auto associated=take(read_military_duty_assignment_association(common,state,accepted.assignment_source.source_ref,accepted.assignment_source.source_schema,4));const auto* issued=take(c.assignments->read_assignment(accepted.assignment_source.source_ref,1));if(!issued||issued!=associated.assignment||issued->id!=request.order_or_assignment_ref||issued->duty_kind!=t.duty_kind||issued->leader_actor_id!=t.leader_actor_id||issued->unit_ids!=t.unit_ids||issued->named_guard_actor_ids!=t.named_guard_actor_ids||issued->fleet_ids!=t.fleet_ids||issued->authorized_until_tick!=t.until_tick||issued->duty_rule_id!=t.duty_rule_id||issued->duty_rule_version!=t.duty_rule_version||issued->qualified_period_policy_ref!=t.qualified_period_policy_ref||issued->route_definition.choice_ref!=request.route_or_station_choice_ref||issued->route_definition.work_acceptance_ref.id!=t.route_or_station_definition_ref||!same_source(issued->supply_authorization.source_ref,t.supply_authorization_ref))fail("MilitaryDutyNativeAssignmentTermsMismatch",request.order_or_assignment_ref);}if(!t.duty_action_id.empty()||t.state!=MilitaryDutyPhase::assembling||t.execution_binding||t.order_or_assignment_ref!=request.order_or_assignment_ref||t.duty_rule_id!=request.duty_rule_id||t.unit_ids!=request.unit_ids||t.named_guard_actor_ids!=request.named_guard_actor_ids||t.fleet_ids!=request.fleet_ids||t.start_tick<0||t.start_tick!=at.half_day_tick||t.until_tick<=t.start_tick||t.leader_actor_id.empty()||t.route_or_station_definition_ref.empty()||!source_valid(t.supply_authorization_ref)||!source_valid(accepted.assignment_source.source_ref)||accepted.assignment_source.source_schema<1)fail("MilitaryDutyAcceptedAssignmentMismatch");const auto& r=rule(c,t);if(t.until_tick-t.start_tick>r.maximum_authorization_half_days)fail("MilitaryDutyAuthorizationTooLong");ids(t.unit_ids,"DuplicateMilitaryDutyUnit");ids(t.named_guard_actor_ids,"DuplicateMilitaryDutyGuard");ids(t.fleet_ids,"DuplicateMilitaryDutyFleet");t.duty_action_id=take(common.next_id("military_duty"));MilitaryDutyAcceptedSource source{take(common.next_id("military_duty_terms")),t.duty_action_id,at,accepted.assignment_source.source_ref,accepted.assignment_source.source_schema};take(c.original.validate_accepted_terms(t,source));MilitaryDutyExecution e;e.duty_action_id=t.duty_action_id;e.accepted_source_ref=source.id;state.terms.set(t.duty_action_id,t);state.executions.set(t.duty_action_id,e);state.accepted_sources.set(source.id,source);take(common.append_fact({source.id,"military_duty_terms","military"}));return MilitaryDutyStartResult{t.duty_action_id,source.id,t.execution_binding,std::move(accepted.journey_request_refs),t.state};});}
